"""Normalize only CSV line endings; compare every saved field before and after."""
import csv,gzip,hashlib,io,json,subprocess
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[3];R=Path(__file__).resolve().parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
rd=lambda p:json.loads(p.read_text())
def put(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
assert not(R/'comparison_csv_format_verification.json').exists()
p=R/'exports/previous_H002_comparisons.csv';raw=p.read_bytes();assert raw.count(b'\r\n')==19
archive=R/'failed_preparation/comparison_original_CRLF.csv.gz';archive.write_bytes(gzip.compress(raw,mtime=0));before_report=sha(R/'report.json');before_account=sha(R/'forward_report.json');b=rd(R/'code_binding_before_evaluation.json');assert all(sha(ROOT/path)==h for path,h in b['source_sha256'].items());doc=rd(R/'previous_H_comparison.json');assert sha(p)==doc['CSV_sha256'];rows=rd(R/'previous_H_comparison.json')['rows'];old_rows=list(csv.DictReader(io.StringIO(raw.decode())));normalized=raw.replace(b'\r\n',b'\n');assert list(csv.DictReader(io.StringIO(normalized.decode())))==old_rows and len(old_rows)==18;p.write_bytes(normalized)
cmd=['git','diff','--no-index','--check','--','/dev/null',str(p)];z=subprocess.run(cmd,cwd=ROOT,capture_output=True,text=True);assert z.returncode in [0,1] and not z.stdout and not z.stderr,(z.returncode,z.stdout,z.stderr)
doc.update(original_CSV_sha256_before_line_endings=hashlib.sha256(raw).hexdigest(),CSV_sha256=sha(p),CSV_line_endings='LF; all original CSV fields preserved',CSV_format_verification=str((R/'comparison_csv_format_verification.json').relative_to(ROOT)));assert doc['rows']==rows;put(R/'previous_H_comparison.json',doc);assert sha(R/'report.json')==before_report and sha(R/'forward_report.json')==before_account and all(sha(ROOT/path)==h for path,h in b['source_sha256'].items())
put(R/'comparison_csv_format_verification.json',{'passed':True,'recorded_utc':datetime.now(timezone.utc).isoformat(),'root_cause':'csv.DictWriter default CRLF produced repository trailing-whitespace errors; only line-ending bytes are normalized after the immutable comparison generator.','initial_actual_failure':{'native_chunk':'849896','command':['git','diff','--no-index','--check','--','/dev/null',str(p)],'exit_code':3,'CRLF_rows':19,'error_excerpt':'previous_H002_comparisons.csv:1: trailing whitespace.'},'original_CSV_archive':str(archive.relative_to(ROOT)),'original_CSV_archive_sha256':sha(archive),'original_uncompressed_CSV_sha256':hashlib.sha256(raw).hexdigest(),'LF_CSV_sha256':sha(p),'CSV_rows_and_every_string_field_equal':True,'saved_numeric_comparison_rows_unchanged':True,'after_actual_whitespace_command':{'command':cmd,'exit_code':z.returncode,'stdout':z.stdout,'stderr':z.stderr,'no_index_file_difference_exit_one_is_expected':z.returncode==1},'financial_report_sha256_unchanged':before_report,'original_account_report_sha256_unchanged':before_account,'all_frozen_financial_creators_unchanged':True,'no_financial_or_account_reexecution':True})
f=R/'read_failures.json';facts=rd(f);facts['facts'].append({'stage':'comparison_export_whitespace','actual_native_chunk':'849896','exit_code':3,'failure':'19 CRLF line endings from the standard CSV writer were flagged as trailing whitespace by the repository check.','resolved':True,'evidence':str((R/'comparison_csv_format_verification.json').relative_to(ROOT)),'original_CSV_archive':str(archive.relative_to(ROOT)),'resolution':'Only CRLF to LF bytes normalized; all 18 rows and every string field identical; financial/account reports and immutable creator sources unchanged.'});put(f,facts)
print(json.dumps({'passed':True,'CSV_rows':18,'numeric_fields_unchanged':True,'financial_or_account_runs':0,'after_no_index_whitespace_exit':z.returncode,'report_sha256_unchanged':before_report}))
